import subprocess

from taf.sw.wtssim import wtssim

from taf.rfrl.csv4all.resources.utilities.utilities import test_logger


class WTS:
    def __init__(self, wts_config: str = "/opt/iphy/latest/basic_setup.cfg", edaemon_port: int = 2222):
        self.wts_config = wts_config
        self.edaemon_port = edaemon_port
        self.wts_dir = "/opt/iphy/latest"
        self.wtssim = wtssim()

    def setup_edaemon_egate(self):
        self.__class__.stop_edaemon_egate_process()
        self.wtssim.setup_edaemon(edaemon_port=self.edaemon_port, tool_dir=self.wts_dir, alias="edaemon_dl")
        self.wtssim.start_edaemon_process(alias="edaemon_dl")
        self.wtssim.setup_edaemon(edaemon_port=30000, tool_dir=self.wts_dir, alias="edaemon_ul")
        self.wtssim.start_edaemon_process(alias="edaemon_ul")
        self.wtssim.setup_egate(egate_port=20000, tool_dir=self.wts_dir)
        self.wtssim.start_egate_process()
        self.execute_wts_config()

    @staticmethod
    def stop_edaemon_egate_process():
        def close_process(process_name: str):
            try:
                pid = subprocess.run(['pgrep', process_name], capture_output=True, text=True, check=True)
                if isinstance(pid, subprocess.CompletedProcess):
                    active_pids = pid.stdout.split("\n")
                    pids = [pid for pid in active_pids if pid]
                    for pid in pids:
                        subprocess.run(["sudo", "kill", "-9", str(pid)])
                else:
                    test_logger(pid, "DEBUG")
                    test_logger(f"Clossing {process_name} process not possible")
            except subprocess.CalledProcessError:
                test_logger(f"{process_name} process not found", "DEBUG")

        for process in ["edaemon", "egate"]:
            close_process(process)

    def reset_wts(self):
        test_logger("Resetting WTS")
        self.wtssim.execute_egate_command_and_wait_for_data(cmd="reset", timeout="300")
        self.execute_wts_config()

    def execute_wts_config(self):
        test_logger("Executing WTS config")
        self.wtssim.execute_egate_command_and_wait_for_data(cmd=f"cfg file={self.wts_config}",
                                                            pass_regexp="(SimMode is ready now|UEC-1 is active)",
                                                            timeout="300")

    def teardown_edaemon_egate(self):
        test_logger("Teardown edaemon and egate")
        self.wtssim.teardown_egate()
        self.wtssim.teardown_all_aliases_for_edaemon()
        self.__class__.stop_edaemon_egate_process()
